import React, { useState } from 'react';
import { FaImage, FaExclamationTriangle } from 'react-icons/fa';

const ImageWithFallback = (props) => {
    const [status, setStatus] = useState('loading');
    const [currentSrc, setCurrentSrc] = useState(props.src);

    const handleLoad = () => setStatus('loaded');

    const handleError = () => {
        setStatus('error');
    };

    return (
        <div className="my-4 relative min-h-[200px] flex flex-col items-center justify-center bg-zinc-900/50 rounded-lg border border-zinc-700/50 overflow-hidden">
            {status === 'loading' && (
                <div className="absolute inset-0 flex flex-col items-center justify-center gap-2 text-zinc-400 animate-pulse">
                    <FaImage className="w-8 h-8 opacity-50" />
                    <span className="text-sm">Generating image...</span>
                </div>
            )}

            {status === 'error' && (
                <div className="absolute inset-0 flex flex-col items-center justify-center gap-2 text-red-400 p-4 text-center">
                    <FaExclamationTriangle className="w-8 h-8 opacity-50" />
                    <span className="text-sm font-medium">Failed to load image</span>
                    <span className="text-xs text-zinc-500 break-all px-4">{currentSrc}</span>
                    <a href={currentSrc} target="_blank" rel="noopener noreferrer" className="text-xs text-blue-400 hover:underline mt-2">
                        Open direct link
                    </a>
                </div>
            )}

            <img
                {...props}
                src={currentSrc}
                className={`rounded-lg shadow-lg max-w-full h-auto transition-opacity duration-300 ${status === 'loaded' ? 'opacity-100' : 'opacity-0'}`}
                onLoad={handleLoad}
                onError={handleError}
                loading="lazy"
                referrerPolicy="no-referrer"
            />
        </div>
    );
};

export default ImageWithFallback;

import { useState, useCallback, useRef } from 'react';
import { API_URL } from '../constants/api';
import { MODELS } from '../constants/models';

export const useChat = (apiHeaders) => {
    const [answer, setAnswer] = useState('');
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');
    const abortControllerRef = useRef(null);

    const resetChat = useCallback(() => {
        setAnswer('');
        setError('');
        setLoading(false);
        if (abortControllerRef.current) {
            abortControllerRef.current.abort();
            abortControllerRef.current = null;
        }
    }, []);



    const sendMessage = useCallback(async (modelId, messages) => {
        resetChat();
        setLoading(true);
        setError('');

        abortControllerRef.current = new AbortController();

        try {
            // Check if selected model is an image generation model
            const selectedModel = MODELS.find(m => m.id === modelId);

            if (selectedModel?.type === 'image') {
                // ... (Pollinations logic remains) ...
                // Extract prompt from the last user message
                const lastMessage = messages[messages.length - 1];
                const promptContent = Array.isArray(lastMessage.content)
                    ? lastMessage.content.find(c => c.type === 'text')?.text
                    : lastMessage.content;

                if (!promptContent) throw new Error('No prompt provided for image generation.');

                const encodedPrompt = encodeURIComponent(promptContent);
                const randomSeed = Math.floor(Math.random() * 100000);

                // Use Weserv.nl global image proxy to bypass 1033/CORS errors completely
                // This routes the request: User -> Weserv -> Pollinations -> User
                // Using image.pollinations.ai/prompt/ API directly as it returns binary image data
                const pollinationUrl = `https://image.pollinations.ai/prompt/${encodedPrompt}?model=${selectedModel.id}&seed=${randomSeed}&nologo=true`;
                const imageUrl = `https://images.weserv.nl/?url=${encodeURIComponent(pollinationUrl)}&output=jpg`;

                // Simulate a slight delay for better UX
                await new Promise(resolve => setTimeout(resolve, 500));

                setAnswer(`![Generated Image](${imageUrl})`);
                setLoading(false);
                return;
            }

            // Handle Paid Image Models (DALL-E 3 via OpenRouter)
            if (selectedModel?.type === 'image-paid') {
                const lastMessage = messages[messages.length - 1];
                const promptContent = Array.isArray(lastMessage.content)
                    ? lastMessage.content.find(c => c.type === 'text')?.text
                    : lastMessage.content;

                // OpenRouter/DALL-E 3 Request
                const response = await fetch(API_URL, {
                    method: 'POST',
                    headers: apiHeaders,
                    body: JSON.stringify({
                        model: modelId,
                        messages: messages,
                        max_tokens: 1000, // Limit max tokens to avoid "insufficient credits" error for large default context
                    }),
                });

                if (!response.ok) {
                    const errJson = await response.json().catch(() => null);
                    throw new Error(errJson?.error?.message || 'Failed to generate image with DALL-E 3');
                }

                const data = await response.json();
                // DALL-E 3 via OpenRouter usually returns content with an image URL in markdown or distinct format
                // OR it acts like a normal chat model that describes the image. 
                // Wait, OpenRouter documentation says DALL-E 3 works via standard chat completions? 
                // Actually, standard OpenAI DALL-E 3 API is /v1/images/generations. 
                // Does OpenRouter proxy that? 
                // Most OpenRouter models are LLMs. 
                // IF OpenRouter supports DALL-E 3, it might return the image URL in the `choices[0].message.content`.

                const content = data.choices?.[0]?.message?.content;
                if (content) {
                    setAnswer(content); // DALL-E 3 often returns the markdown image directly or a description + URL
                } else {
                    throw new Error('No content returned from DALL-E 3');
                }

                setLoading(false);
                return;
            }

            const response = await fetch(API_URL, {
                method: 'POST',
                headers: apiHeaders, // ensure headers are clean for standard request
                body: JSON.stringify({
                    model: modelId,
                    messages: messages,
                    stream: true, // Enable streaming
                }),
                signal: abortControllerRef.current.signal,
            });

            if (!response.ok) {
                const errJson = await response.json().catch(() => null);
                console.error('API Error Details:', errJson); // Log full error details
                const errMsg = errJson?.error?.message || response.statusText || 'Request failed';
                throw new Error(errMsg);
            }

            if (!response.body) throw new Error('ReadableStream not supported in this browser.');

            const reader = response.body.getReader();
            const decoder = new TextDecoder();


            let fullAnswer = '';

            while (true) {
                const { done, value } = await reader.read();
                if (done) break;

                const chunk = decoder.decode(value, { stream: true });
                const lines = chunk.split('\n');

                for (const line of lines) {
                    if (line.trim() === '') continue;
                    if (line.trim() === 'data: [DONE]') continue;

                    if (line.startsWith('data: ')) {
                        try {
                            const data = JSON.parse(line.slice(6));
                            const content = data.choices?.[0]?.delta?.content || '';
                            if (content) {
                                fullAnswer += content;
                                setAnswer((prev) => prev + content);
                            }
                        } catch (e) {
                            console.warn('Error parsing stream chunk', e);
                        }
                    }
                }
            }
            return fullAnswer;
        } catch (err) {
            if (err.name !== 'AbortError') {
                setError(err.message || 'Something went wrong.');
            }
            throw err; // Re-throw to handle in component
        } finally {
            setLoading(false);
            abortControllerRef.current = null;
        }
    }, [apiHeaders, resetChat]);

    return {
        answer,
        loading,
        error,
        sendMessage,
        resetChat,
    };
};
